def accounts_merge(accounts):
    adj, owner = defaultdict(list), {}
    for name, *emails in accounts:
        for e in emails:
            owner[e] = name
            adj[emails[0]].append(e)
            adj[e].append(emails[0])
    seen, out = set(), []
    for e in owner:
        if e in seen:
            continue
        seen.add(e)
        stack, group = [e], []
        while stack:
            x = stack.pop()
            group.append(x)
            for nb in adj[x]:
                if nb not in seen:
                    seen.add(nb)
                    stack.append(nb)
        out.append([owner[e]] + sorted(group))
    return out

def accounts_merge(accounts):
    parent = list(range(len(accounts)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    first_owner = {}
    for i, (_, *emails) in enumerate(accounts):
        for e in emails:
            if e in first_owner:
                parent[find(i)] = find(first_owner[e])
            else:
                first_owner[e] = i
    groups = defaultdict(list)
    for e, i in first_owner.items():
        groups[find(i)].append(e)
    return [[accounts[root][0]] + sorted(es) for root, es in groups.items()]
